function proposal(storyId: string, digest: string): HostKeywordProposal {
  return {
    schemaVersion: 'proofbound.keyword-proposal.v1',
    storyId,
    host: 'codex-cli',
    proposalId: 'p1',
    promptDigest: 'prompt-1',
    deterministicSeedDigest: digest,
    terms: [{
